import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"GitHub agent","description":"Run prioricode from GitHub issues and PRs — the Actions workflow, @mention triggers, hosted app vs OIDC vs PAT modes, and scheduled runs.","frontmatter":{"title":"GitHub agent","description":"Run prioricode from GitHub issues and PRs — the Actions workflow, @mention triggers, hosted app vs OIDC vs PAT modes, and scheduled runs."},"headers":[],"relativePath":"platforms/github.md","filePath":"platforms/github.md"}'),n={name:"platforms/github.md"};function o(r,e,h,l,d,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<p>Comment <code>/prioricode fix this</code> on an issue and an agent picks up your repo <strong>on your own GitHub runners</strong>, opens a branch, and sends a PR. The GitHub agent is the same engine pointed at events instead of a terminal.</p><h2 id="trigger-surface" tabindex="-1">Trigger surface <a class="header-anchor" href="#trigger-surface" aria-label="Permalink to &quot;Trigger surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>What happens</th></tr></thead><tbody><tr><td><code>issue_comment</code> containing <code>/prioricode</code> or <code>/pc</code></td><td>The agent acts on the issue: explain it, or fix it (branch + PR).</td></tr><tr><td><code>pull_request_review_comment</code></td><td>Line-specific review with file/diff context; requested changes get committed back to the same PR.</td></tr><tr><td><code>schedule</code> / <code>workflow_dispatch</code></td><td>Headless repo tasks — nightly triage, weekly audits — whatever prompt the workflow defines.</td></tr></tbody></table><p>The mention tokens are configurable (<code>mentions</code> input), so <code>/pc</code> for the keyboard-honest.</p><h2 id="install-it" tabindex="-1">Install it <a class="header-anchor" href="#install-it" aria-label="Permalink to &quot;Install it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>The command walks the three moving parts: installing the GitHub App (<code>github.com/apps/prioricode-agent</code>), creating the workflow at <code>.github/workflows/prioricode.yml</code>, and wiring secrets/OIDC. The resulting workflow calls <code>Prioritech-Indonesia-Optima/prioricode/github@latest</code>.</p><p>Three auth routes, pick by policy:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Setup</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Hosted app (default)</strong></td><td>App installed on the repo; workflow gets <code>id-token: write</code></td><td>Actions authenticate via OIDC to the hosted exchange, which mints a scoped GitHub token per run.</td></tr><tr><td><strong>Plain <code>GITHUB_TOKEN</code></strong></td><td><code>use_github_token: true</code> in inputs</td><td>No app at all — runs with the workflow&#39;s own token. Fewer moving parts, the same default permissions model.</td></tr><tr><td><strong>PAT</strong></td><td><code>--token</code>/secret (<code>github_pat_…</code>)</td><td>Escape hatch for dry runs and testing.</td></tr></tbody></table><h3 id="workflow-inputs" tabindex="-1">Workflow inputs <a class="header-anchor" href="#workflow-inputs" aria-label="Permalink to &quot;Workflow inputs&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic/claude-sonnet-4-5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # required — provider/model, as everywhere else</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # any agent: built-in or your custom</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;triage new issues nightly&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # for schedule/dispatch runs</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mentions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/prioricode,/pc&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  share</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # publish the session transcript (see sharing)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  variant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span></code></pre></div><h2 id="test-locally-before-it-runs-on-ci" tabindex="-1">Test locally before it runs on CI <a class="header-anchor" href="#test-locally-before-it-runs-on-ci" aria-label="Permalink to &quot;Test locally before it runs on CI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --event</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./fixtures/issue-comment.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PAT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Replays a GitHub event JSON against a real session — the loop is fast enough to iterate on prompts against fixtures.</p><h2 id="what-to-expect-from-it" tabindex="-1">What to expect from it <a class="header-anchor" href="#what-to-expect-from-it" aria-label="Permalink to &quot;What to expect from it&quot;">​</a></h2><ul><li><strong>Issues</strong>: it reads the thread, explores the repo, then either comments an explanation or opens a PR with the fix. No silent pushes to protected branches — it works the way outside collaborators do.</li><li><strong>PR reviews</strong>: it reviews <em>changes</em>, answers follow-up comments on the same PR, and commits requested fixes to the PR branch when asked.</li><li><strong>Everything is a session</strong>: runs can be shared (<code>share: true</code>) so a review thread links to the agent&#39;s actual transcript — receipts included.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The action executes with your workflow&#39;s permissions — that&#39;s the whole security story in one sentence. Scope the app/<code>GITHUB_TOKEN</code> the way you&#39;d scope any bot: contents read/write on target repos, nothing more, and keep secrets out of <code>prompt</code>. The threat model discussion lives in <a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p></div><h2 id="bonus-the-pr-command" tabindex="-1">Bonus: the <code>pr</code> command <a class="header-anchor" href="#bonus-the-pr-command" aria-label="Permalink to &quot;Bonus: the \`pr\` command&quot;">​</a></h2><p>Locally: <code>prioricode pr 4813</code> fetches and checks out the PR branch (needs <code>gh</code>), auto-imports the agent&#39;s session if the PR body links one, and opens the TUI on that branch. Review-and-iterate round-trips without touching the mouse.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../using/headless.html">Headless</a> — The same story for non-GitHub CI. <ul><li><a href="./../using/sharing.html">Sharing</a> — What <code>share: true</code> actually produces.</li><li><a href="./../using/agents.html">Agents</a> — Pick (or build) the agent the bot runs.</li></ul></li></ul>`,21)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
